import * as React from "react"

function ButtonWithBouncingAnimation({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="button-with-bouncing-animation"
      className={className}
      {...props}
    >
      <a href=""
          className="animate-bounce focus hover inline-flex text-md font-medium bg-indigo-900 mt-3 px-4 py-2 rounded-lg tracking-wide text-white">
          <span className="ml-2">Bouncing Button 🏀</span>
      </a>
    </div>
  )
}

export { ButtonWithBouncingAnimation }
